style.css:
@-moz-document domain("roblox.com") {
/* Base background */
  body, html {
    background-color: #e9f5ff !important;
    color: #1b1b1b !important;
    font-family: 'Poppins', 'Segoe UI', sans-serif !important;
    transition: background-color 0.3s ease-in-out;
  }

  /* Top navigation bar */
  .navbar, .header, .rbx-navbar {
    background-color: #cfe9ff !important;
    border-bottom: 1px solid #b3d9ff !important;
    box-shadow: 0 2px 6px rgba(0,0,0,0.05) !important;
  }

  /* Game tiles */
  .game-card, .game-card-container {
    background-color: #ffffff !important;
    border-radius: 12px !important;
    box-shadow: 0 3px 8px rgba(0,0,0,0.08) !important;
    transition: transform 0.25s ease-in-out, box-shadow 0.25s ease-in-out;
  }

  .game-card:hover {
    transform: scale(1.02);
    box-shadow: 0 0 10px rgba(129, 206, 255, 0.6) !important;
  }

  /* Buttons */
  button, .btn-common, .btn-primary, .btn-control {
    background-color: #8cc8ff !important;
    color: #ffffff !important;
    border-radius: 10px !important;
    border: none !important;
    transition: background-color 0.2s ease-in-out, transform 0.15s ease-in-out;
  }

  button:hover, .btn-common:hover, .btn-primary:hover {
    background-color: #5bb6ff !important;
    transform: scale(1.03);
  }

  /* Sidebar */
  .left-col, .sidebar, .vertical-menu {
    background-color: #dff0ff !important;
    border-right: 1px solid #b6dcff !important;
  }

  /* Input fields */
  input, textarea, .input-field {
    background-color: #f4fbff !important;
    color: #1b1b1b !important;
    border: 1px solid #a7d5ff !important;
    border-radius: 8px !important;
    padding: 6px 10px !important;
  }

  input:focus, textarea:focus {
    border-color: #66bfff !important;
    outline: none !important;
    box-shadow: 0 0 6px rgba(102,191,255,0.4) !important;
  }

  /* Links */
  a {
    color: #339aff !important;
    text-decoration: none !important;
    font-weight: 500 !important;
  }

  a:hover {
    color: #0078e7 !important;
  }

  /* Game titles */
  .game-name, .text-name, .game-title {
    color: #0f4c81 !important;
  }

  /* Remove ad banners (optional) */
  .ad-container, .ads-container, #Skyscraper-Abp-Right, #Leaderboard-Abp {
    display: none !important;
  }
}
